# Port the engineering-agent pipeline to the LunchPad iOS repo.
#
# Writes 5 files (2 GitHub Actions workflows + 3 agent runner scripts),
# adapted for Expo: the build gate is `expo export` (a real JS bundle)
# instead of `next build`, and the agent guardrails target the iOS
# code (lib/api.ts contract, Apple Sign In, the theme system).
#
# All the web-pipeline hardening is carried over: resilient self-review,
# the type-safety guard, fail-closed auto-merge.
#
# Run from C:\Faheed Code\lunchpad-ios

$ErrorActionPreference = "Stop"
$root = "C:\Faheed Code\lunchpad-ios"
Set-Location $root

Remove-Item .git\*.lock -ErrorAction SilentlyContinue

git fetch origin
git checkout main
git reset --hard origin/main
git checkout -B chore/agent-pipeline

function Write-B64($path, $b64) {
  $full = Join-Path $root $path
  $dir = Split-Path $full
  if (-not (Test-Path $dir)) { New-Item -ItemType Directory -Force -Path $dir | Out-Null }
  [IO.File]::WriteAllBytes($full, [Convert]::FromBase64String($b64))
  Write-Host "wrote $path" -ForegroundColor Green
}

Write-B64 ".github\workflows\eng-agent.yml"      ""
Write-B64 ".github\workflows\agent-fix.yml"      ""
Write-B64 "scripts\agent\run-eng.sh"             ""
Write-B64 "scripts\agent\run-fix.sh"             ""
Write-B64 "scripts\agent\run-self-review.sh"     ""

git add .github/workflows/eng-agent.yml .github/workflows/agent-fix.yml `
  scripts/agent/run-eng.sh scripts/agent/run-fix.sh scripts/agent/run-self-review.sh

git commit -m "Add engineering-agent pipeline (ported from web repo, adapted for Expo)"
git push -u origin chore/agent-pipeline

$pr = gh pr create --repo faheeds/lunchpad-ios --base main --head chore/agent-pipeline `
  --title "Add engineering-agent pipeline" `
  --body "Ports the LunchPad web engineering-agent pipeline to this repo so iOS issues can be worked the same way. Adapted for Expo: the build gate is expo export (a real iOS JS bundle) instead of next build; agent guardrails target iOS code (the lib/api.ts mobile API contract, Apple Sign In, the theme system). All web-pipeline hardening is carried over: 3x-retry resilient self-review that never fails open, a type-safety guard that blocks auto-merge on new as-any / ts-ignore, and auto-merge gated on tsc + tests + bundle + guard + a real PASS verdict."
Write-Host ""
Write-Host "PR opened: $pr" -ForegroundColor Green
Write-Host ""
Write-Host "=== AFTER MERGING THIS PR, two manual setup steps (one-time) ===" -ForegroundColor Cyan
Write-Host "1. Add two repo secrets to faheeds/lunchpad-ios (Settings -> Secrets -> Actions," -ForegroundColor Yellow
Write-Host "   or via CLI - each command prompts for the value):" -ForegroundColor Yellow
Write-Host "     gh secret set ANTHROPIC_API_KEY --repo faheeds/lunchpad-ios" -ForegroundColor Yellow
Write-Host "     gh secret set AGENT_PAT         --repo faheeds/lunchpad-ios" -ForegroundColor Yellow
Write-Host "   (AGENT_PAT = a GitHub PAT with repo scope covering lunchpad-ios -" -ForegroundColor Yellow
Write-Host "    the same one the web repo uses works if it is a classic repo-scoped token.)" -ForegroundColor Yellow
Write-Host "2. Settings -> General -> enable 'Allow auto-merge'." -ForegroundColor Yellow
Write-Host ""
Write-Host "Merge once ready:" -ForegroundColor Yellow
Write-Host "  gh pr merge --repo faheeds/lunchpad-ios --squash --delete-branch chore/agent-pipeline" -ForegroundColor Yellow
